package vn.somehouse;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.test.web.servlet.MockMvc;import org.springframework.jdbc.core.JdbcTemplate;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;
@SpringBootTest @AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SOMEHOUSE_INTEGRATION_DB_URL",matches=".+") class SqlServerIntegrationTest {
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->System.getenv("SOMEHOUSE_INTEGRATION_DB_URL"));r.add("spring.datasource.username",()->System.getenv("SOMEHOUSE_INTEGRATION_DB_USER"));r.add("spring.datasource.password",()->System.getenv("SOMEHOUSE_INTEGRATION_DB_PASSWORD"));r.add("app.admin-email",()->"");r.add("app.seed-enabled",()->true);}
 @Autowired MockMvc mvc;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;
 @Test void sqlServerUnicodeFiltersAndPagination()throws Exception{mvc.perform(get("/api/v1/properties").param("q","quy nhon").param("size","3").param("sort","price_asc")).andExpect(status().isOk()).andExpect(jsonPath("$.items.length()").value(3));assertEquals(58,db.queryForObject("SELECT COUNT(*) FROM catalog_items WHERE kind='PROPERTY'",Integer.class));}
 @Test void repeatedLeadRequestCreatesExactlyOneRow()throws Exception{String key=UUID.randomUUID().toString(),body="{\"name\":\"Khách kiểm thử\",\"phone\":\"0972158609\",\"email\":\"integration@example.invalid\",\"purpose\":\"INQUIRY\",\"message\":\"Yêu cầu tích hợp\"}";try{String first=mvc.perform(post("/api/v1/leads").with(csrf()).header("Idempotency-Key",key).contentType("application/json").content(body)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();String second=mvc.perform(post("/api/v1/leads").with(csrf()).header("Idempotency-Key",key).contentType("application/json").content(body)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();assertEquals(json.readTree(first).path("reference"),json.readTree(second).path("reference"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM leads WHERE idempotency_key=?",Integer.class,key));}finally{db.update("DELETE FROM leads WHERE idempotency_key=?",key);}}
 @Test void adminCrudHasOptimisticLockingAndDraftIsolation()throws Exception{String slug="integration-"+UUID.randomUUID();String body="{\"kind\":\"ARTICLE\",\"slug\":\""+slug+"\",\"titleVi\":\"Bài kiểm thử\",\"coverUrl\":\"/image/somehouse-icon.svg\",\"price\":0,\"area\":0,\"bedrooms\":0,\"published\":false,\"version\":0,\"data\":{}}";long id=0;try{var result=mvc.perform(post("/api/v1/admin/items").with(user("test").roles("ADMIN")).with(csrf()).contentType("application/json").content(body)).andExpect(status().isCreated()).andReturn();id=json.readTree(result.getResponse().getContentAsString()).path("id").asLong();mvc.perform(get("/api/v1/articles/"+slug)).andExpect(status().isNotFound());mvc.perform(put("/api/v1/admin/items/"+id).with(user("test").roles("ADMIN")).with(csrf()).contentType("application/json").content(body)).andExpect(status().isOk());mvc.perform(put("/api/v1/admin/items/"+id).with(user("test").roles("ADMIN")).with(csrf()).contentType("application/json").content(body)).andExpect(status().isConflict());}finally{if(id!=0)db.update("DELETE FROM catalog_items WHERE id=?",id);}}
}
